insert into public.sources (title, url, kind, publisher, published_on) values ('Real Academia Española · Diccionario de la lengua española (dle.rae.es): entradas seleccionadas con sus sinónimos y antónimos', 'https://dle.rae.es/', 'web_oficial'::public.source_kind, 'Real Academia Española y ASALE', null) on conflict (url) do nothing;
