   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-aux-b1-07-transparencia', 'I.7 La Ley 19/2013 de transparencia, acceso a la información pública y buen gobierno') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxiliar-administrativo-estado') and t.slug = 'age-aux-b1-07-transparencia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Objeto de la Ley 19/2013 (art. 1)"},{"n":"2","title":"Transparencia: ámbito subjetivo (arts. 2-4)"},{"n":"3","title":"Publicidad activa (arts. 5-11)"},{"n":"3.1","title":"Obligaciones de publicación (arts. 5-8)"},{"n":"3.2","title":"Control y Portal de la Transparencia (arts. 9-11)"},{"n":"4","title":"Derecho de acceso a la información pública (arts. 12-24)"},{"n":"4.1","title":"Titulares, concepto y límites (arts. 12-16)"},{"n":"4.2","title":"Solicitud, tramitación y resolución (arts. 17-22)"},{"n":"4.3","title":"Reclamación ante el Consejo de Transparencia y Buen Gobierno (arts. 23-24)"},{"n":"5","title":"Buen gobierno: principios, infracciones y sanciones (arts. 25-32)"},{"n":"6","title":"El Consejo de Transparencia y Buen Gobierno (arts. 33-40)"}]'::jsonb, '["Art. 1 Ley 19/2013: «Esta Ley tiene por objeto ampliar y reforzar la transparencia de la actividad pública, regular y garantizar el derecho de acceso a la información relativa a aquella actividad y establecer las obligaciones de buen gobierno que deben cumplir los responsables públicos así como las consecuencias derivadas de su incumplimiento.»","Art. 3.b) Ley 19/2013: «Las entidades privadas que perciban durante el período de un año ayudas o subvenciones públicas en una cuantía superior a 100.000 euros o cuando al menos el 40 % del total de sus ingresos anuales tengan carácter de ayuda o subvención pública, siempre que alcancen como mínimo la cantidad de 5.000 euros.»","Art. 5.1 Ley 19/2013: «Los sujetos enumerados en el artículo 2.1 publicarán de forma periódica y actualizada la información cuyo conocimiento sea relevante para garantizar la transparencia de su actividad relacionada con el funcionamiento y control de la actuación pública.»","Art. 9.3 Ley 19/2013: «El incumplimiento reiterado de las obligaciones de publicidad activa reguladas en este capítulo tendrá la consideración de infracción grave a los efectos de aplicación a sus responsables del régimen disciplinario previsto en la correspondiente normativa reguladora.»","Art. 10.1 Ley 19/2013: «La Administración General del Estado desarrollará un Portal de la Transparencia, dependiente del Ministerio de la Presidencia, que facilitará el acceso de los ciudadanos a toda la información a la que se refieren los artículos anteriores relativa a su ámbito de actuación.»","Art. 12 Ley 19/2013: «Todas las personas tienen derecho a acceder a la información pública, en los términos previstos en el artículo 105.b) de la Constitución Española, desarrollados por esta Ley.»","Art. 13 Ley 19/2013: «Se entiende por información pública los contenidos o documentos, cualquiera que sea su formato o soporte, que obren en poder de alguno de los sujetos incluidos en el ámbito de aplicación de este título y que hayan sido elaborados o adquiridos en el ejercicio de sus funciones.»","Art. 17.3 Ley 19/2013: «El solicitante no está obligado a motivar su solicitud de acceso a la información.»","Art. 20.1 Ley 19/2013: «La resolución en la que se conceda o deniegue el acceso deberá notificarse al solicitante y a los terceros afectados que así lo hayan solicitado en el plazo máximo de un mes desde la recepción de la solicitud por el órgano competente para resolver. Este plazo podrá ampliarse por otro mes en el caso de que el volumen o la complejidad de la información que se solicita así lo hagan necesario y previa notificación al solicitante.»","Art. 20.4 Ley 19/2013: «Transcurrido el plazo máximo para resolver sin que se haya dictado y notificado resolución expresa se entenderá que la solicitud ha sido desestimada.»","Art. 22.4 Ley 19/2013: «El acceso a la información será gratuito.»","Art. 24.1 Ley 19/2013: «Frente a toda resolución expresa o presunta en materia de acceso podrá interponerse una reclamación ante el Consejo de Transparencia y Buen Gobierno, con carácter potestativo y previo a su impugnación en vía contencioso-administrativa.»","Art. 24.4 Ley 19/2013: «El plazo máximo para resolver y notificar la resolución será de tres meses, transcurrido el cual, la reclamación se entenderá desestimada.»","Art. 32.1 Ley 19/2013: «El plazo de prescripción de las infracciones previstas en este título será de cinco años para las infracciones muy graves, tres años para las graves y un año para las leves.»","Art. 33.2 Ley 19/2013: «El Consejo de Transparencia y Buen Gobierno tiene personalidad jurídica propia y plena capacidad de obrar. Actúa con autonomía y plena independencia en el cumplimiento de sus fines.»","Art. 37.1 Ley 19/2013: «El Presidente del Consejo de Transparencia y Buen Gobierno será nombrado por un período no renovable de cinco años mediante Real Decreto»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Objeto de la Ley 19/2013 (art. 1)","blocks":[{"text":"La Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno (LT), tiene un triple objeto: ampliar y reforzar la transparencia de la actividad pública, regular y garantizar el derecho de acceso a la información sobre esa actividad, y establecer las obligaciones de buen gobierno de los responsables públicos y las consecuencias de su incumplimiento (art. 1). La estructura de la Ley sigue ese orden: Título I (transparencia: publicidad activa y derecho de acceso), Título II (buen gobierno) y Título III (Consejo de Transparencia y Buen Gobierno).","refs":[{"ref":"Art. 1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Esta Ley tiene por objeto ampliar y reforzar la transparencia de la actividad pública, regular y garantizar el derecho de acceso a la información relativa a aquella actividad y establecer las obligaciones de buen gobierno que deben cumplir los responsables públicos así como las consecuencias derivadas de su incumplimiento."},{"ref":"Títulos de la LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"TÍTULO I. Transparencia de la actividad pública […] TÍTULO II. Buen gobierno […] TÍTULO III. Consejo de Transparencia y Buen Gobierno"}]},{"text":"Aviso de actualidad: el texto consolidado recogido sigue remitiendo en varios artículos a normas ya sustituidas, como la Ley 30/1992 (arts. 23, 24, 30, 32 y 39), y a denominaciones ministeriales antiguas («Ministerio de Hacienda y Administraciones Públicas», «Ministerio de la Presidencia»). Las fuentes recogidas para este tema no indican cómo se leen hoy esas remisiones, así que en el examen conviene responder con la letra de la Ley.","refs":[{"ref":"Art. 23.1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"de conformidad con lo dispuesto en el artículo 107.2 de la Ley 30/1992, de 26 de noviembre, de Régimen Jurídico de las Administraciones Públicas y del Procedimiento Administrativo Común."},{"ref":"Art. 33.1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Estará adscrito al Ministerio de Hacienda y Administraciones Públicas."}]}]},{"n":"2","title":"Transparencia: ámbito subjetivo (arts. 2-4)","blocks":[{"text":"El Título I se aplica, entre otros (art. 2.1): a la Administración General del Estado, a las de las Comunidades Autónomas, Ceuta y Melilla y a las entidades locales; a las entidades gestoras y servicios comunes de la Seguridad Social y a las mutuas; a organismos autónomos, Agencias Estatales, entidades públicas empresariales y entidades de Derecho Público, incluidas las Universidades públicas; y a las corporaciones de Derecho Público en sus actividades sujetas a Derecho Administrativo. Solo las letras a) a d) son «Administraciones Públicas» a efectos de este título (art. 2.2).","refs":[{"ref":"Art. 2.1.a) LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"a) La Administración General del Estado, las Administraciones de las Comunidades Autónomas y de las Ciudades de Ceuta y Melilla y las entidades que integran la Administración Local."},{"ref":"Art. 2.1.d) y e) LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"d) Las entidades de Derecho Público con personalidad jurídica propia, vinculadas a cualquiera de las Administraciones Públicas o dependientes de ellas, incluidas las Universidades públicas. e) Las corporaciones de Derecho Público, en lo relativo a sus actividades sujetas a Derecho Administrativo."},{"ref":"Art. 2.2 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"A los efectos de lo previsto en este título, se entiende por Administraciones Públicas los organismos y entidades incluidos en las letras a) a d) del apartado anterior."}]},{"text":"También quedan sujetos, en sus actividades sujetas a Derecho Administrativo, la Casa de S.M. el Rey, el Congreso, el Senado, el Tribunal Constitucional, el CGPJ, el Banco de España, el Consejo de Estado, el Defensor del Pueblo, el Tribunal de Cuentas y el Consejo Económico y Social (art. 2.1.f). Y las sociedades mercantiles con participación pública directa o indirecta superior al 50 por 100, las fundaciones del sector público y las asociaciones constituidas por estas entidades (art. 2.1.g a i).","refs":[{"ref":"Art. 2.1.f) LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"La Casa de su Majestad el Rey, el Congreso de los Diputados, el Senado, el Tribunal Constitucional y el Consejo General del Poder Judicial, así como el Banco de España, el Consejo de Estado, el Defensor del Pueblo, el Tribunal de Cuentas, el Consejo Económico y Social y las instituciones autonómicas análogas, en relación con sus actividades sujetas a Derecho Administrativo."},{"ref":"Art. 2.1.g) y h) LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"g) Las sociedades mercantiles en cuyo capital social la participación, directa o indirecta, de las entidades previstas en este artículo sea superior al 50 por 100. h) Las fundaciones del sector público previstas en la legislación en materia de fundaciones."}]},{"text":"Otros sujetos obligados (art. 3), solo a la publicidad activa (capítulo II): los partidos políticos, sindicatos y organizaciones empresariales, y las entidades privadas que reciban en un año ayudas o subvenciones superiores a 100.000 euros, o cuando al menos el 40 % de sus ingresos anuales sean ayudas públicas, siempre que alcancen como mínimo 5.000 euros. Además, quienes presten servicios públicos o ejerzan potestades administrativas deben suministrar, previo requerimiento, la información necesaria a la Administración a la que estén vinculados (art. 4).","refs":[{"ref":"Art. 3 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Las disposiciones del capítulo II de este título serán también aplicables a: a) Los partidos políticos, organizaciones sindicales y organizaciones empresariales. b) Las entidades privadas que perciban durante el período de un año ayudas o subvenciones públicas en una cuantía superior a 100.000 euros o cuando al menos el 40 % del total de sus ingresos anuales tengan carácter de ayuda o subvención pública, siempre que alcancen como mínimo la cantidad de 5.000 euros."},{"ref":"Art. 4 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Las personas físicas y jurídicas distintas de las referidas en los artículos anteriores que presten servicios públicos o ejerzan potestades administrativas estarán obligadas a suministrar a la Administración, organismo o entidad de las previstas en el artículo 2.1 a la que se encuentren vinculadas, previo requerimiento, toda la información necesaria"}]}]},{"n":"3","title":"Publicidad activa: obligaciones de publicación (arts. 5-8)","blocks":[{"text":"Publicidad activa es la información que se publica sin que nadie la pida. Los sujetos del art. 2.1 publican de forma periódica y actualizada la información relevante para la transparencia (art. 5.1). Se aplican los límites del art. 14 y la protección de datos del art. 15; los datos especialmente protegidos se publican disociados (art. 5.3). La información se publica en sedes electrónicas o webs, de forma clara y, preferiblemente, en formatos reutilizables (art. 5.4), y será comprensible, de acceso fácil y gratuito y accesible a personas con discapacidad (art. 5.5).","refs":[{"ref":"Art. 5.1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Los sujetos enumerados en el artículo 2.1 publicarán de forma periódica y actualizada la información cuyo conocimiento sea relevante para garantizar la transparencia de su actividad relacionada con el funcionamiento y control de la actuación pública."},{"ref":"Art. 5.3 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"cuando la información contuviera datos especialmente protegidos, la publicidad sólo se llevará a cabo previa disociación de los mismos."},{"ref":"Art. 5.4 y 5.5 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"La información sujeta a las obligaciones de transparencia será publicada en las correspondientes sedes electrónicas o páginas web y de una manera clara, estructurada y entendible para los interesados y, preferiblemente, en formatos reutilizables. […] Toda la información será comprensible, de acceso fácil y gratuito y estará a disposición de las personas con discapacidad"}]},{"text":"La Ley agrupa lo que debe publicarse en tres bloques. Información institucional, organizativa y de planificación: funciones, normativa, estructura y un organigrama actualizado, además de planes y programas; en la AGE evalúan su cumplimiento las inspecciones generales de servicios (art. 6). Información de relevancia jurídica: directrices e instrucciones que interpreten el Derecho, anteproyectos de ley, proyectos de reglamento y memorias normativas (art. 7).","refs":[{"ref":"Art. 6 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"incluirán un organigrama actualizado que identifique a los responsables de los diferentes órganos y su perfil y trayectoria profesional. […] En el ámbito de la Administración General del Estado corresponde a las inspecciones generales de servicios la evaluación del cumplimiento de estos planes y programas."},{"ref":"Art. 7.a) y b) LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"a) Las directrices, instrucciones, acuerdos, circulares o respuestas a consultas planteadas por los particulares u otros órganos en la medida en que supongan una interpretación del Derecho o tengan efectos jurídicos. b) Los Anteproyectos de Ley y los proyectos de Decretos Legislativos cuya iniciativa les corresponda"}]},{"text":"Información económica, presupuestaria y estadística (art. 8): contratos (los menores pueden publicarse trimestralmente), convenios y encomiendas de gestión, subvenciones con importe y beneficiarios, presupuestos y su ejecución, cuentas anuales, retribuciones anuales de altos cargos, resoluciones de compatibilidad y declaraciones de bienes de los representantes locales. Las Administraciones publican también sus bienes inmuebles (art. 8.3).","refs":[{"ref":"Art. 8.1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"La publicación de la información relativa a los contratos menores podrá realizarse trimestralmente. […] c) Las subvenciones y ayudas públicas concedidas con indicación de su importe, objetivo o finalidad y beneficiarios. […] f) Las retribuciones percibidas anualmente por los altos cargos y máximos responsables de las entidades incluidas en el ámbito de la aplicación de este título."},{"ref":"Art. 8.3 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Las Administraciones Públicas publicarán la relación de los bienes inmuebles que sean de su propiedad o sobre los que ostenten algún derecho real."}]}]},{"n":"4","title":"Control y Portal de la Transparencia (arts. 9-11)","blocks":[{"text":"El cumplimiento de la publicidad activa por la AGE lo controla el Consejo de Transparencia y Buen Gobierno, que puede dictar resoluciones con medidas para que cese el incumplimiento (art. 9.1 y 9.2). El incumplimiento reiterado de estas obligaciones es infracción grave a efectos disciplinarios (art. 9.3).","refs":[{"ref":"Art. 9.1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"El cumplimiento por la Administración General del Estado de las obligaciones contenidas en este capítulo será objeto de control por parte del Consejo de Transparencia y Buen Gobierno."},{"ref":"Art. 9.3 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"El incumplimiento reiterado de las obligaciones de publicidad activa reguladas en este capítulo tendrá la consideración de infracción grave a los efectos de aplicación a sus responsables del régimen disciplinario previsto en la correspondiente normativa reguladora."}]},{"text":"La AGE desarrolla un Portal de la Transparencia, dependiente del Ministerio de la Presidencia según la letra de la Ley, que incluye también la información cuyo acceso se solicita con mayor frecuencia (art. 10). Debe respetar tres principios técnicos: accesibilidad, interoperabilidad (conforme al Esquema Nacional de Interoperabilidad) y reutilización (art. 11).","refs":[{"ref":"Art. 10.1 y 10.2 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"La Administración General del Estado desarrollará un Portal de la Transparencia, dependiente del Ministerio de la Presidencia, que facilitará el acceso de los ciudadanos a toda la información a la que se refieren los artículos anteriores relativa a su ámbito de actuación. 2. El Portal de la Transparencia incluirá, en los términos que se establezcan reglamentariamente, la información de la Administración General del Estado, cuyo acceso se solicite con mayor frecuencia."},{"ref":"Art. 11 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"a) Accesibilidad […] b) Interoperabilidad: la información publicada será conforme al Esquema Nacional de Interoperabilidad […] c) Reutilización"}]}]},{"n":"5","title":"Derecho de acceso: titulares, concepto y límites (arts. 12-16)","blocks":[{"text":"Todas las personas tienen derecho a acceder a la información pública, en los términos del art. 105.b) CE (art. 12). Información pública son los contenidos o documentos, cualquiera que sea su formato o soporte, que obren en poder de los sujetos del Título I y que hayan sido elaborados o adquiridos en el ejercicio de sus funciones (art. 13).","refs":[{"ref":"Art. 12 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Todas las personas tienen derecho a acceder a la información pública, en los términos previstos en el artículo 105.b) de la Constitución Española, desarrollados por esta Ley."},{"ref":"Art. 13 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Se entiende por información pública los contenidos o documentos, cualquiera que sea su formato o soporte, que obren en poder de alguno de los sujetos incluidos en el ámbito de aplicación de este título y que hayan sido elaborados o adquiridos en el ejercicio de sus funciones."}]},{"text":"El acceso puede limitarse cuando suponga un perjuicio para doce bienes (art. 14.1): seguridad nacional; defensa; relaciones exteriores; seguridad pública; prevención e investigación de ilícitos; igualdad de las partes en los procesos judiciales; funciones de vigilancia, inspección y control; intereses económicos y comerciales; política económica y monetaria; secreto profesional y propiedad intelectual e industrial; confidencialidad en la toma de decisiones; y protección del medio ambiente. Los límites se aplican de forma justificada y proporcionada, atendiendo a un posible interés público o privado superior (art. 14.2).","refs":[{"ref":"Art. 14.1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"El derecho de acceso podrá ser limitado cuando acceder a la información suponga un perjuicio para: a) La seguridad nacional. b) La defensa. c) Las relaciones exteriores. d) La seguridad pública. e) La prevención, investigación y sanción de los ilícitos penales, administrativos o disciplinarios. f) La igualdad de las partes en los procesos judiciales y la tutela judicial efectiva. g) Las funciones administrativas de vigilancia, inspección y control. h) Los intereses económicos y comerciales. i) La política económica y monetaria. j) El secreto profesional y la propiedad intelectual e industrial. k) La garantía de la confidencialidad o el secreto requerido en procesos de toma de decisión. l) La protección del medio ambiente."},{"ref":"Art. 14.2 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"La aplicación de los límites será justificada y proporcionada a su objeto y finalidad de protección y atenderá a las circunstancias del caso concreto, especialmente a la concurrencia de un interés público o privado superior que justifique el acceso."}]},{"text":"Protección de datos (art. 15): si hay datos sobre ideología, afiliación sindical, religión o creencias, hace falta consentimiento expreso y por escrito del afectado, salvo que él mismo los hubiera hecho manifiestamente públicos. Para origen racial, salud, vida sexual, datos genéticos o biométricos o infracciones sin amonestación pública basta consentimiento expreso o una norma con rango de ley. Los datos meramente identificativos de la organización se conceden con carácter general (art. 15.2). Si un límite afecta solo a parte de la información, se concede acceso parcial (art. 16).","refs":[{"ref":"Art. 15.1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Si la información solicitada contuviera datos personales que revelen la ideología, afiliación sindical, religión o creencias, el acceso únicamente se podrá autorizar en caso de que se contase con el consentimiento expreso y por escrito del afectado, a menos que dicho afectado hubiese hecho manifiestamente públicos los datos con anterioridad a que se solicitase el acceso."},{"ref":"Art. 15.1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"el acceso solo se podrá autorizar en caso de que se cuente con el consentimiento expreso del afectado o si aquel estuviera amparado por una norma con rango de ley."},{"ref":"Art. 16 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"En los casos en que la aplicación de alguno de los límites previstos en el artículo 14 no afecte a la totalidad de la información, se concederá el acceso parcial previa omisión de la información afectada por el límite"}]}]},{"n":"6","title":"Solicitud y tramitación (arts. 17-19)","blocks":[{"text":"La solicitud se dirige al titular del órgano o entidad que posea la información (art. 17.1) y puede presentarse por cualquier medio que deje constancia de la identidad del solicitante, la información pedida, una dirección de contacto (preferentemente electrónica) y, en su caso, la modalidad de acceso preferida (art. 17.2). No hay que motivarla, aunque se pueden exponer motivos; la falta de motivación no es por sí sola causa de rechazo (art. 17.3). Puede usarse cualquier lengua cooficial del territorio (art. 17.4).","refs":[{"ref":"Art. 17.2 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"a) La identidad del solicitante. b) La información que se solicita. c) Una dirección de contacto, preferentemente electrónica, a efectos de comunicaciones. d) En su caso, la modalidad que se prefiera para acceder a la información solicitada."},{"ref":"Art. 17.3 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"El solicitante no está obligado a motivar su solicitud de acceso a la información. Sin embargo, podrá exponer los motivos por los que solicita la información y que podrán ser tenidos en cuenta cuando se dicte la resolución. No obstante, la ausencia de motivación no será por si sola causa de rechazo de la solicitud."}]},{"text":"Se inadmiten, por resolución motivada, cinco tipos de solicitudes (art. 18.1): información en curso de elaboración o publicación general; información auxiliar o de apoyo (notas, borradores, opiniones, resúmenes, informes internos); información que exija una acción previa de reelaboración; solicitudes dirigidas a un órgano que no tiene la información cuando se desconozca el competente (en ese caso hay que indicar el órgano competente, art. 18.2); y las manifiestamente repetitivas o abusivas.","refs":[{"ref":"Art. 18.1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"a) Que se refieran a información que esté en curso de elaboración o de publicación general. b) Referidas a información que tenga carácter auxiliar o de apoyo como la contenida en notas, borradores, opiniones, resúmenes, comunicaciones e informes internos o entre órganos o entidades administrativas. c) Relativas a información para cuya divulgación sea necesaria una acción previa de reelaboración. d) Dirigidas a un órgano en cuyo poder no obre la información cuando se desconozca el competente. e) Que sean manifiestamente repetitivas o tengan un carácter abusivo no justificado con la finalidad de transparencia de esta Ley."}]},{"text":"Tramitación (art. 19): si el órgano no tiene la información, la remite al competente y lo comunica. Si la solicitud no identifica bien la información, se pide que se concrete en diez días, con aviso de desistimiento y suspensión del plazo. Si puede afectar a terceros identificados, se les dan quince días para alegaciones, también con suspensión del plazo.","refs":[{"ref":"Art. 19.2 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Cuando la solicitud no identifique de forma suficiente la información, se pedirá al solicitante que la concrete en un plazo de diez días, con indicación de que, en caso de no hacerlo, se le tendrá por desistido, así como de la suspensión del plazo para dictar resolución."},{"ref":"Art. 19.3 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Si la información solicitada pudiera afectar a derechos o intereses de terceros, debidamente identificados, se les concederá un plazo de quince días para que puedan realizar las alegaciones que estimen oportunas."}]}]},{"n":"7","title":"Resolución y formalización del acceso (arts. 20-22)","blocks":[{"text":"La resolución se notifica en el plazo máximo de un mes desde la recepción de la solicitud por el órgano competente, ampliable por otro mes por volumen o complejidad, previa notificación al solicitante (art. 20.1). Deben motivarse las que deniegan, las que conceden acceso parcial o por modalidad distinta y las que conceden pese a la oposición de un tercero (art. 20.2). El silencio es negativo: pasado el plazo sin resolución expresa, la solicitud se entiende desestimada (art. 20.4). El incumplimiento reiterado de resolver en plazo es infracción grave (art. 20.6).","refs":[{"ref":"Art. 20.1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"La resolución en la que se conceda o deniegue el acceso deberá notificarse al solicitante y a los terceros afectados que así lo hayan solicitado en el plazo máximo de un mes desde la recepción de la solicitud por el órgano competente para resolver. Este plazo podrá ampliarse por otro mes en el caso de que el volumen o la complejidad de la información que se solicita así lo hagan necesario y previa notificación al solicitante."},{"ref":"Art. 20.2 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Serán motivadas las resoluciones que denieguen el acceso, las que concedan el acceso parcial o a través de una modalidad distinta a la solicitada y las que permitan el acceso cuando haya habido oposición de un tercero."},{"ref":"Art. 20.4 y 20.6 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Transcurrido el plazo máximo para resolver sin que se haya dictado y notificado resolución expresa se entenderá que la solicitud ha sido desestimada. […] El incumplimiento reiterado de la obligación de resolver en plazo tendrá la consideración de infracción grave"}]},{"text":"El acceso se realiza preferentemente por vía electrónica; si no puede darse con la notificación, debe darse en un plazo no superior a diez días (art. 22.1). Si hubo oposición de tercero, se espera a que pase el plazo del recurso contencioso (art. 22.2). El acceso es gratuito, aunque la expedición de copias o el cambio de formato pueden generar tasas o precios (art. 22.4). En la AGE existen unidades de información especializadas que tramitan las solicitudes y llevan su registro (art. 21.2).","refs":[{"ref":"Art. 22.1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"El acceso a la información se realizará preferentemente por vía electrónica, salvo cuando no sea posible o el solicitante haya señalado expresamente otro medio. Cuando no pueda darse el acceso en el momento de la notificación de la resolución deberá otorgarse, en cualquier caso, en un plazo no superior a diez días."},{"ref":"Art. 22.4 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"El acceso a la información será gratuito. No obstante, la expedición de copias o la trasposición de la información a un formato diferente al original podrá dar lugar a la exigencia de exacciones"},{"ref":"Art. 21.2 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"b) Recibir y dar tramitación a las solicitudes de acceso a la información. […] e) Llevar un registro de las solicitudes de acceso a la información."}]}]},{"n":"8","title":"Reclamación ante el Consejo de Transparencia y Buen Gobierno (arts. 23-24)","blocks":[{"text":"Las resoluciones de acceso son recurribles directamente ante la jurisdicción contencioso-administrativa, sin perjuicio de la reclamación potestativa (art. 20.5). Esa reclamación sustituye a los recursos administrativos (art. 23.1), pero contra las resoluciones de los órganos del art. 2.1.f (Casa del Rey, Cortes, TC, CGPJ, etc.) solo cabe recurso contencioso-administrativo (art. 23.2).","refs":[{"ref":"Art. 20.5 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Las resoluciones dictadas en materia de acceso a la información pública son recurribles directamente ante la Jurisdicción Contencioso-administrativa, sin perjuicio de la posibilidad de interposición de la reclamación potestativa prevista en el artículo 24."},{"ref":"Art. 23 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"La reclamación prevista en el artículo siguiente tendrá la consideración de sustitutiva de los recursos administrativos […] 2. No obstante lo dispuesto en el apartado anterior, contra las resoluciones dictadas por los órganos previstos en el artículo 2.1.f) sólo cabrá la interposición de recurso contencioso-administrativo."}]},{"text":"La reclamación ante el Consejo de Transparencia y Buen Gobierno cabe frente a resoluciones expresas o presuntas, es potestativa y previa a la vía contenciosa (art. 24.1). Se interpone en un mes desde el día siguiente a la notificación o a los efectos del silencio (art. 24.2). Si la denegación se basó en derechos de terceros, se les da audiencia (art. 24.3). El plazo máximo para resolver y notificar es de tres meses; si no, se entiende desestimada (art. 24.4). Las resoluciones se publican disociando datos personales y se comunican al Defensor del Pueblo (art. 24.5).","refs":[{"ref":"Art. 24.1 y 24.2 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Frente a toda resolución expresa o presunta en materia de acceso podrá interponerse una reclamación ante el Consejo de Transparencia y Buen Gobierno, con carácter potestativo y previo a su impugnación en vía contencioso-administrativa. 2. La reclamación se interpondrá en el plazo de un mes a contar desde el día siguiente al de la notificación del acto impugnado o desde el día siguiente a aquel en que se produzcan los efectos del silencio administrativo."},{"ref":"Art. 24.4 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"El plazo máximo para resolver y notificar la resolución será de tres meses, transcurrido el cual, la reclamación se entenderá desestimada."},{"ref":"Art. 24.5 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"El Presidente del Consejo de Transparencia y Buen Gobierno comunicará al Defensor del Pueblo las resoluciones que dicte en aplicación de este artículo."}]}]},{"n":"9","title":"Buen gobierno: ámbito y principios (arts. 25-26)","blocks":[{"text":"El Título II se aplica a los miembros del Gobierno, Secretarios de Estado y demás altos cargos de la AGE y del sector público estatal, y a los altos cargos autonómicos y locales, incluidos los miembros de las Juntas de Gobierno locales (art. 25). Su aplicación no afecta a la condición de cargo electo (art. 25.3).","refs":[{"ref":"Art. 25.1 y 25.2 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"se aplicarán a los miembros del Gobierno, a los Secretarios de Estado y al resto de los altos cargos de la Administración General del Estado y de las entidades del sector público estatal […] incluidos los miembros de las Juntas de Gobierno de las Entidades Locales."}]},{"text":"El art. 26 distingue principios generales (transparencia, dedicación al servicio público, imparcialidad, igualdad de trato, diligencia, conducta digna, responsabilidad) y principios de actuación. Entre estos: plena dedicación, reserva sobre lo conocido por el cargo, no aceptar regalos que superen los usos habituales, sociales o de cortesía (los de mayor relevancia institucional pasan al patrimonio de la Administración) y no valerse de la posición para obtener ventajas. Estos principios informan la interpretación del régimen sancionador (art. 26.3).","refs":[{"ref":"Art. 26.2.b) LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"6.º No aceptarán para sí regalos que superen los usos habituales, sociales o de cortesía, ni favores o servicios en condiciones ventajosas que puedan condicionar el desarrollo de sus funciones. En el caso de obsequios de una mayor relevancia institucional se procederá a su incorporación al patrimonio de la Administración Pública correspondiente."},{"ref":"Art. 26.3 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Los principios establecidos en este artículo informarán la interpretación y aplicación del régimen sancionador regulado en este título."}]}]},{"n":"10","title":"Buen gobierno: infracciones, sanciones y prescripción (arts. 27-32)","blocks":[{"text":"Hay tres bloques de infracciones: en materia de conflicto de intereses (art. 27, que remite a su normativa propia), de gestión económico-presupuestaria (art. 28, todas muy graves cuando sean culpables, como comprometer gastos sin crédito suficiente) y disciplinarias (art. 29, muy graves, graves y leves). Por ejemplo, el acoso laboral es muy grave, el abuso de autoridad es grave y la incorrección con superiores o compañeros es leve.","refs":[{"ref":"Art. 28 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Constituyen infracciones muy graves las siguientes conductas cuando sean culpables: […] c) Los compromisos de gastos, reconocimiento de obligaciones y ordenación de pagos sin crédito suficiente para realizarlos"},{"ref":"Art. 29 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"k) El acoso laboral. […] 2. Son infracciones graves: a) El abuso de autoridad en el ejercicio del cargo. […] 3. Son infracciones leves: a) La incorrección con los superiores, compañeros o subordinados."}]},{"text":"Sanciones (art. 30): las leves, con amonestación; las graves, con la declaración del incumplimiento y su publicación en el BOE o diario oficial, o la pérdida de la indemnización por cese; las muy graves llevan esas sanciones y, además, la destitución y la prohibición de ser nombrado alto cargo durante cinco a diez años. Si los hechos pueden ser delito, se comunica al Fiscal General del Estado y se suspende el procedimiento (art. 30.6).","refs":[{"ref":"Art. 30 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"1. Las infracciones leves serán sancionadas con una amonestación. 2. Por la comisión de una infracción grave se impondrán al infractor algunas de las siguientes sanciones: a) La declaración del incumplimiento y su publicación en el «Boletín Oficial del Estado» o diario oficial que corresponda. b) La no percepción, en el caso de que la llevara aparejada, de la correspondiente indemnización para el caso de cese en el cargo. 3. En el caso de las infracciones muy graves, se impondrán en todo caso las sanciones previstas en el apartado anterior."},{"ref":"Art. 30.4 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Los sancionados por la comisión de una infracción muy grave serán destituidos del cargo que ocupen salvo que ya hubiesen cesado y no podrán ser nombrados para ocupar ningún puesto de alto cargo o asimilado durante un periodo de entre cinco y diez años"},{"ref":"Art. 30.6 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Cuando las infracciones pudieran ser constitutivas de delito, la Administración pondrá los hechos en conocimiento del Fiscal General del Estado"}]},{"text":"El procedimiento se inicia de oficio (art. 31.1). Si el responsable es miembro del Gobierno o Secretario de Estado, ordena la incoación y sanciona el Consejo de Ministros; la instrucción corresponde a la Oficina de Conflictos de Intereses (art. 31). Prescripción de infracciones y de sanciones: cinco años las muy graves, tres las graves y uno las leves (art. 32).","refs":[{"ref":"Art. 31.3 y 31.4 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"la instrucción de los correspondientes procedimientos corresponderá a la Oficina de Conflictos de Intereses. […] a) Al Consejo de Ministros cuando el alto cargo tenga la condición de miembro del Gobierno o Secretario de Estado."},{"ref":"Art. 32 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"1. El plazo de prescripción de las infracciones previstas en este título será de cinco años para las infracciones muy graves, tres años para las graves y un año para las leves. 2. Las sanciones impuestas por la comisión de infracciones muy graves prescribirán a los cinco años, las impuestas por infracciones graves a los tres años y las que sean consecuencia de la comisión de infracciones leves prescribirán en el plazo de un año."}]}]},{"n":"11","title":"El Consejo de Transparencia y Buen Gobierno (arts. 33-40)","blocks":[{"text":"El Consejo de Transparencia y Buen Gobierno (CTBG) es un organismo público con personalidad jurídica propia y plena capacidad de obrar, que actúa con autonomía y plena independencia (art. 33.2). Su finalidad es promover la transparencia, velar por la publicidad activa, salvaguardar el derecho de acceso y garantizar el buen gobierno (art. 34). Sus órganos son la Comisión de Transparencia y Buen Gobierno y el Presidente, que lo es también de la Comisión (art. 35).","refs":[{"ref":"Art. 33.2 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"El Consejo de Transparencia y Buen Gobierno tiene personalidad jurídica propia y plena capacidad de obrar. Actúa con autonomía y plena independencia en el cumplimiento de sus fines."},{"ref":"Art. 35 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"a) La Comisión de Transparencia y Buen Gobierno. b) El Presidente del Consejo de Transparencia y Buen Gobierno que lo será también de su Comisión."}]},{"text":"La Comisión la forman el Presidente, un Diputado, un Senador y un representante de cada uno de estos: Tribunal de Cuentas, Defensor del Pueblo, Agencia Española de Protección de Datos, Secretaría de Estado de Administraciones Públicas y Autoridad Independiente de Responsabilidad Fiscal (art. 36.2). Ser miembro no exige dedicación exclusiva ni da derecho a remuneración, salvo el Presidente (art. 36.3).","refs":[{"ref":"Art. 36.2 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"a) El Presidente. b) Un Diputado. c) Un Senador. d) Un representante del Tribunal de Cuentas. e) Un representante del Defensor del Pueblo. f) Un representante de la Agencia Española de Protección de Datos. g) Un representante de la Secretaría de Estado de Administraciones Públicas. h) Un representante de la Autoridad Independiente de Responsabilidad Fiscal."},{"ref":"Art. 36.3 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"La condición de miembro de la Comisión del Consejo de Transparencia y Buen Gobierno no exigirá dedicación exclusiva ni dará derecho a remuneración con excepción de lo previsto en el artículo siguiente."}]},{"text":"El Presidente es nombrado por Real Decreto para un periodo no renovable de cinco años, entre personas de reconocido prestigio, tras comparecer ante la Comisión del Congreso, que debe refrendar el nombramiento por mayoría absoluta en un mes (art. 37.1). Entre sus funciones: adoptar criterios de interpretación uniforme, conocer de las reclamaciones del art. 24 e instar el procedimiento sancionador (art. 38.2). El CTBG eleva cada año a las Cortes una memoria, y su Presidente comparece para darle cuenta (art. 40).","refs":[{"ref":"Art. 37.1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"El Presidente del Consejo de Transparencia y Buen Gobierno será nombrado por un período no renovable de cinco años mediante Real Decreto […] El Congreso, a través de la Comisión competente y por acuerdo adoptado por mayoría absoluta, deberá refrendar el nombramiento del candidato propuesto en el plazo de un mes natural desde la recepción de la correspondiente comunicación."},{"ref":"Art. 38.2 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"a) Adoptar criterios de interpretación uniforme de las obligaciones contenidas en esta Ley. […] c) Conocer de las reclamaciones que se presenten en aplicación del artículo 24 de esta Ley."},{"ref":"Art. 40 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"El Consejo de Transparencia y Buen Gobierno elevará anualmente a las Cortes Generales una memoria sobre el desarrollo de sus actividades y sobre el grado de cumplimiento de las disposiciones establecidas en esta Ley."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Partidos, sindicatos y organizaciones empresariales: solo publicidad activa. Entidades privadas: más de 100.000 euros de ayudas al año, o el 40 % de sus ingresos con un mínimo de 5.000 euros.","refs":[{"ref":"Art. 3.b) LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"en una cuantía superior a 100.000 euros o cuando al menos el 40 % del total de sus ingresos anuales tengan carácter de ayuda o subvención pública, siempre que alcancen como mínimo la cantidad de 5.000 euros."}]},{"text":"Sociedades mercantiles sujetas: participación pública superior al 50 por 100.","refs":[{"ref":"Art. 2.1.g) LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"sea superior al 50 por 100."}]},{"text":"Plazos de la solicitud: diez días para concretar, quince días de alegaciones de terceros, un mes para resolver (más otro), diez días para dar el acceso. Silencio negativo.","refs":[{"ref":"Art. 20.4 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"se entenderá que la solicitud ha sido desestimada."}]},{"text":"Reclamación ante el CTBG: potestativa, en un mes; el CTBG resuelve en tres meses (silencio desestimatorio).","refs":[{"ref":"Art. 24.4 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"El plazo máximo para resolver y notificar la resolución será de tres meses"}]},{"text":"Datos de ideología, afiliación sindical, religión o creencias: consentimiento expreso y por escrito.","refs":[{"ref":"Art. 15.1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"consentimiento expreso y por escrito del afectado"}]},{"text":"Sanciones: leve, amonestación; muy grave, destitución e inhabilitación para alto cargo de cinco a diez años. Prescripción: 5, 3 y 1 años.","refs":[{"ref":"Art. 30.1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"Las infracciones leves serán sancionadas con una amonestación."}]},{"text":"Presidente del CTBG: cinco años no renovables, por Real Decreto, refrendo del Congreso por mayoría absoluta.","refs":[{"ref":"Art. 37.1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"será nombrado por un período no renovable de cinco años mediante Real Decreto"}]},{"text":"Portal de la Transparencia: lo desarrolla la AGE y depende, según la Ley, del Ministerio de la Presidencia.","refs":[{"ref":"Art. 10.1 LT","law":"Ley 19/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887","quote":"La Administración General del Estado desarrollará un Portal de la Transparencia, dependiente del Ministerio de la Presidencia"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887', null, null, null, null
